"""Exact, branchable packet-scheduling experiment engine.

The module uses persistent (path-copying) search trees for every structure that
can contain a packet.  Savepoints therefore share the resident population and
only copy the small control arrays.  All packet ordering is expressed by
integer keys; no floating-point arithmetic is used.
"""

from __future__ import annotations

import sys
from bisect import bisect_right

# Deep persistent treaps are expected to be shallow; this also leaves ample
# room for the iterative collectors.
sys.setrecursionlimit(1_000_000)

_MASK64 = (1 << 64) - 1


def _splitmix64(value: int) -> int:
    value &= _MASK64
    value = (value + 0x9E3779B97F4A7C15) & _MASK64
    value = ((value ^ (value >> 30)) * 0xBF58476D1CE4E5B9) & _MASK64
    value = ((value ^ (value >> 27)) * 0x94D049BB133111EB) & _MASK64
    return (value ^ (value >> 31)) & _MASK64


class Packet:
    __slots__ = ("id", "flow", "length", "flow_size", "rank", "ordinal",
                 "bank", "key", "prio")

    def __init__(self, pkt_id, flow, length, flow_size, rank, ordinal, bank):
        self.id = pkt_id
        self.flow = flow
        self.length = length
        self.flow_size = flow_size
        self.rank = rank
        self.ordinal = ordinal
        self.bank = bank
        self.key = (rank, ordinal)
        # Ordinals are unique.  SplitMix64 is a bijection on 64-bit words, so
        # distinct packets also get distinct priorities.
        self.prio = _splitmix64(ordinal ^ 0xD1B54A32D192ED03)


# ---------------------------------------------------------------------------
# Per-bank staging FIFO (keys are persistent packet ordinals)
# ---------------------------------------------------------------------------

class FNode:
    __slots__ = ("pkt", "left", "right", "size", "bytes")

    def __init__(self, pkt, left=None, right=None):
        self.pkt = pkt
        self.left = left
        self.right = right
        self.size = 1 + (left.size if left is not None else 0) + \
            (right.size if right is not None else 0)
        self.bytes = pkt.length + \
            (left.bytes if left is not None else 0) + \
            (right.bytes if right is not None else 0)


def f_merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.pkt.prio > b.pkt.prio:
        return FNode(a.pkt, a.left, f_merge(a.right, b))
    return FNode(b.pkt, f_merge(a, b.left), b.right)


def f_insert_last(root, pkt):
    """Insert a packet whose ordinal is greater than every key in root."""
    if root is None:
        return FNode(pkt)
    if pkt.prio > root.pkt.prio:
        return FNode(pkt, root, None)
    return FNode(root.pkt, root.left, f_insert_last(root.right, pkt))


def f_delete(root, ordinal):
    if root is None:
        return None
    key = root.pkt.ordinal
    if ordinal < key:
        return FNode(root.pkt, f_delete(root.left, ordinal), root.right)
    if ordinal > key:
        return FNode(root.pkt, root.left, f_delete(root.right, ordinal))
    return f_merge(root.left, root.right)


def f_find(root, ordinal):
    while root is not None:
        key = root.pkt.ordinal
        if ordinal == key:
            return True
        root = root.left if ordinal < key else root.right
    return False


def f_split_count(root, count):
    """Return (first `count` packets, remaining packets)."""
    if root is None:
        return None, None
    if count <= 0:
        return None, root
    if count >= root.size:
        return root, None
    left_size = root.left.size if root.left is not None else 0
    if count < left_size:
        first, rest_left = f_split_count(root.left, count)
        return first, FNode(root.pkt, rest_left, root.right)
    if count == left_size:
        right = FNode(root.pkt, None, root.right)
        return root.left, right
    if count == left_size + 1:
        left = FNode(root.pkt, root.left, None)
        return left, root.right
    first_right, rest = f_split_count(root.right,
                                      count - left_size - 1)
    return FNode(root.pkt, root.left, first_right), rest


def f_collect(root):
    out = []
    stack = []
    node = root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        out.append(node.pkt)
        node = node.right
    return out


# ---------------------------------------------------------------------------
# Per-bank PIFO (keys are immutable (rank, ordinal) pairs)
# ---------------------------------------------------------------------------

class PNode:
    __slots__ = ("pkt", "left", "right", "size", "bytes")

    def __init__(self, pkt, left=None, right=None):
        self.pkt = pkt
        self.left = left
        self.right = right
        self.size = 1 + (left.size if left is not None else 0) + \
            (right.size if right is not None else 0)
        self.bytes = pkt.length + \
            (left.bytes if left is not None else 0) + \
            (right.bytes if right is not None else 0)


def p_merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.pkt.prio > b.pkt.prio:
        return PNode(a.pkt, a.left, p_merge(a.right, b))
    return PNode(b.pkt, p_merge(a, b.left), b.right)


def p_split(root, key):
    """Split by (rank, ordinal): keys < key, then keys >= key."""
    if root is None:
        return None, None
    if root.pkt.key < key:
        first, rest = p_split(root.right, key)
        return PNode(root.pkt, root.left, first), rest
    first, rest = p_split(root.left, key)
    return first, PNode(root.pkt, rest, root.right)


def p_insert(root, pkt):
    if root is None:
        return PNode(pkt)
    if pkt.prio > root.pkt.prio:
        left, right = p_split(root, pkt.key)
        return PNode(pkt, left, right)
    if pkt.key < root.pkt.key:
        return PNode(root.pkt, p_insert(root.left, pkt), root.right)
    if pkt.key > root.pkt.key:
        return PNode(root.pkt, root.left, p_insert(root.right, pkt))
    # Keys are unique in one branch; defensively replace the resident value.
    return PNode(pkt, root.left, root.right)


def p_delete(root, key):
    if root is None:
        return None
    if key < root.pkt.key:
        return PNode(root.pkt, p_delete(root.left, key), root.right)
    if key > root.pkt.key:
        return PNode(root.pkt, root.left, p_delete(root.right, key))
    return p_merge(root.left, root.right)


def p_find(root, key):
    while root is not None:
        k = root.pkt.key
        if key == k:
            return True
        root = root.left if key < k else root.right
    return False


def p_pop_min(root):
    """Remove and return (minimum packet, new root).  root must be nonempty."""
    if root.left is None:
        return root.pkt, root.right
    pkt, new_left = p_pop_min(root.left)
    return pkt, PNode(root.pkt, new_left, root.right)


def p_take_prefix(root, cap):
    """Split into the longest in-order prefix with byte sum <= cap.

    Returned as (retained, evicted_suffix).  Both trees remain ordered.  The
    early total-bytes test keeps the common no-pushout path O(1).
    """
    if root is None:
        return None, None
    if root.bytes <= cap:
        return root, None
    left_bytes = root.left.bytes if root.left is not None else 0
    if left_bytes > cap:
        retained, evicted_left = p_take_prefix(root.left, cap)
        return retained, PNode(root.pkt, evicted_left, root.right)
    remaining = cap - left_bytes
    if root.pkt.length > remaining:
        return root.left, PNode(root.pkt, None, root.right)
    retained_right, evicted_right = p_take_prefix(
        root.right, remaining - root.pkt.length)
    return PNode(root.pkt, root.left, retained_right), evicted_right
    return PNode(root.pkt, root.left, retained_right), evicted_right


def p_collect(root):
    out = []
    stack = []
    node = root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        out.append(node.pkt)
        node = node.right
    return out


# ---------------------------------------------------------------------------
# Global live set: (rank, ordinal) treap with prefix lag increments
# ---------------------------------------------------------------------------

class GNode:
    __slots__ = ("pkt", "left", "right", "size", "lag", "lazy")

    def __init__(self, pkt, left=None, right=None, lag=0, lazy=0):
        self.pkt = pkt
        self.left = left
        self.right = right
        self.size = 1 + (left.size if left is not None else 0) + \
            (right.size if right is not None else 0)
        self.lag = lag
        self.lazy = lazy


def g_apply(node, delta):
    if node is None or delta == 0:
        return node
    return GNode(node.pkt, node.left, node.right,
                 node.lag + delta, node.lazy + delta)


def g_push(node):
    """Materialise a node's pending child increment."""
    if node is None or node.lazy == 0:
        return node
    delta = node.lazy
    return GNode(node.pkt, g_apply(node.left, delta),
                 g_apply(node.right, delta), node.lag, 0)


def g_merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.pkt.prio > b.pkt.prio:
        a = g_push(a)
        return GNode(a.pkt, a.left, g_merge(a.right, b), a.lag, 0)
    b = g_push(b)
    return GNode(b.pkt, g_merge(a, b.left), b.right, b.lag, 0)


def g_split_key(root, key):
    if root is None:
        return None, None
    root = g_push(root)
    if root.pkt.key < key:
        first, rest = g_split_key(root.right, key)
        return GNode(root.pkt, root.left, first, root.lag, 0), rest
    first, rest = g_split_key(root.left, key)
    return first, GNode(root.pkt, rest, root.right, root.lag, 0)


def g_split_rank(root, rank):
    """Split into packets with rank < rank and packets with rank >= rank."""
    if root is None:
        return None, None
    root = g_push(root)
    if root.pkt.rank < rank:
        first, rest = g_split_rank(root.right, rank)
        return GNode(root.pkt, root.left, first, root.lag, 0), rest
    first, rest = g_split_rank(root.left, rank)
    return first, GNode(root.pkt, rest, root.right, root.lag, 0)


def g_insert(root, pkt):
    first, rest = g_split_key(root, pkt.key)
    return g_merge(g_merge(first, GNode(pkt)), rest)


def g_delete(root, key):
    if root is None:
        return None
    root = g_push(root)
    if key < root.pkt.key:
        return GNode(root.pkt, g_delete(root.left, key), root.right,
                     root.lag, 0)
    if key > root.pkt.key:
        return GNode(root.pkt, root.left, g_delete(root.right, key),
                     root.lag, 0)
    return g_merge(root.left, root.right)


def g_get_lag(root, key):
    """Return (effective lag, packet), or (None, None)."""
    extra = 0
    node = root
    while node is not None:
        if key == node.pkt.key:
            return node.lag + extra, node.pkt
        extra += node.lazy
        node = node.left if key < node.pkt.key else node.right
    return None, None


def g_less_rank_and_increment(root, rank):
    """Count keys with rank < rank, then add one lag unit to that prefix."""
    first, rest = g_split_rank(root, rank)
    count = first.size if first is not None else 0
    first = g_apply(first, 1)
    return count, g_merge(first, rest)


def g_collect_lags(root):
    """Return (packet id, effective lag) pairs in unspecified order."""
    out = []
    if root is None:
        return out
    stack = [(root, 0)]
    while stack:
        node, carry = stack.pop()
        out.append((node.pkt.id, node.lag + carry))
        child_carry = carry + node.lazy
        if node.left is not None:
            stack.append((node.left, child_carry))
        if node.right is not None:
            stack.append((node.right, child_carry))
    return out


# ---------------------------------------------------------------------------
# Persistent flow-id -> value map for WFQ
# ---------------------------------------------------------------------------

class FlowNode:
    __slots__ = ("key", "value", "prio", "left", "right")

    def __init__(self, key, value, prio, left=None, right=None):
        self.key = key
        self.value = value
        self.prio = prio
        self.left = left
        self.right = right


def _flow_prio(key):
    return _splitmix64(key ^ 0xA24BAED4963EE407)


def flow_split(root, key):
    if root is None:
        return None, None
    if root.key < key:
        first, rest = flow_split(root.right, key)
        return FlowNode(root.key, root.value, root.prio,
                        root.left, first), rest
    first, rest = flow_split(root.left, key)
    return first, FlowNode(root.key, root.value, root.prio,
                           rest, root.right)


def flow_set(root, key, value):
    if root is None:
        return FlowNode(key, value, _flow_prio(key))
    if key == root.key:
        return FlowNode(key, value, root.prio, root.left, root.right)
    new_prio = _flow_prio(key)
    if new_prio > root.prio:
        left, right = flow_split(root, key)
        return FlowNode(key, value, new_prio, left, right)
    if key < root.key:
        return FlowNode(root.key, root.value, root.prio,
                        flow_set(root.left, key, value), root.right)
    return FlowNode(root.key, root.value, root.prio,
                    root.left, flow_set(root.right, key, value))


def flow_get(root, key):
    while root is not None:
        if key == root.key:
            return root.value
        root = root.left if key < root.key else root.right
    raise KeyError(key)


# ---------------------------------------------------------------------------
# Rank policies
# ---------------------------------------------------------------------------

class FifoPolicy:
    kind = "fifo"

    def __init__(self, spec):
        self.time = 0

    def attempt(self, flow, length, flow_size):
        self.time += 1
        return self.time

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "fifo", "time": self.time}

    def snapshot(self):
        return (self.time,)

    def restore(self, data):
        self.time = data[0]


class SpPolicy:
    kind = "sp"

    def __init__(self, spec):
        levels = spec.get("levels", [])
        self.levels = sorted((int(flow), int(level))
                             for flow, level in levels)
        self.lookup = dict(self.levels)

    def attempt(self, flow, length, flow_size):
        return self.lookup[flow]

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "sp",
                "levels": [[flow, level] for flow, level in self.levels]}

    def snapshot(self):
        return None

    def restore(self, data):
        pass


class SffPolicy:
    kind = "sff"

    def __init__(self, spec):
        pass

    def attempt(self, flow, length, flow_size):
        return flow_size

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "sff"}

    def snapshot(self):
        return None

    def restore(self, data):
        pass


class WfqPolicy:
    kind = "wfq"
    kind = "wfq"

    def __init__(self, spec):
        weights = sorted((int(flow), int(weight))
                         for flow, weight in spec.get("weights", []))
        self.flow_ids = [flow for flow, _ in weights]
        self.weights = None
        self.finish = None
        for flow, weight in weights:
            self.weights = flow_set(self.weights, flow, weight)
            self.finish = flow_set(self.finish, flow, 0)
        self.virtual_time = 0

    def attempt(self, flow, length, flow_size):
        weight = flow_get(self.weights, flow)
        old_finish = flow_get(self.finish, flow)
        base = old_finish if old_finish > self.virtual_time \
            else self.virtual_time
        new_finish = base + (length * 1048576 + weight - 1) // weight
        self.finish = flow_set(self.finish, flow, new_finish)
        return new_finish

    def service(self, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def update_weight(self, flow, weight):
        self.weights = flow_set(self.weights, flow, weight)

    def certificate(self):
        return {
            "kind": "wfq",
            "virtual_time": self.virtual_time,
            "weights": [[flow, flow_get(self.weights, flow)]
                        for flow in self.flow_ids],
            "finish": [[flow, flow_get(self.finish, flow)]
                       for flow in self.flow_ids],
        }

    def snapshot(self):
        return (self.virtual_time, self.weights, self.finish)

    def restore(self, data):
        self.virtual_time, self.weights, self.finish = data


def make_policy(spec):
    kind = spec.get("kind")
    if kind == "fifo":
        return FifoPolicy(spec)
    if kind == "sp":
        return SpPolicy(spec)
    if kind == "sff":
        return SffPolicy(spec)
    if kind == "wfq":
        return WfqPolicy(spec)
    raise ValueError("unknown policy")


# ---------------------------------------------------------------------------
# Savepoint
# ---------------------------------------------------------------------------

class Snapshot:
    __slots__ = ("tick", "load_balancer", "service_bank", "sample_progress",
                 "borders", "counters", "history", "policy", "fifos", "pifos",
                 "global_root")

    def __init__(self, engine):
        self.tick = engine.tick
        self.load_balancer = engine.load_balancer
        self.service_bank = engine.service_bank
        self.sample_progress = engine.sample_progress
        self.borders = tuple(engine.borders)
        self.counters = tuple(
            tuple(tuple(row) for row in lb)
            for lb in engine.counters
        )
        self.history = tuple(engine.history)
        self.policy = engine.policy.snapshot()
        self.fifos = tuple(engine.fifos)
        self.pifos = tuple(engine.pifos)
        self.global_root = engine.global_root


# ---------------------------------------------------------------------------
# One run
# ---------------------------------------------------------------------------

class RunEngine:
    def __init__(self, run):
        self.banks = int(run["banks"])
        self.load_balancers = int(run["load_balancers"])
        self.fifo_capacity = int(run["fifo_bytes"])
        self.pifo_capacity = int(run["pifo_bytes"])
        self.refill_batch = int(run["refill_batch"])
        self.sample_period = int(run["sample_period"])
        self.borders = [int(x) for x in run["borders"]]

        ranges = len(self.borders) - 1
        banks = self.banks
        lcount = self.load_balancers
        self.counters = [
            [
                [1 if q < (r % banks) else 0 for r in range(ranges)]
                for q in range(banks)
            ]
            for _ in range(lcount)
        ]
        self.history = [0 for _ in range(ranges)]

        self.tick = 0
        self.load_balancer = 0
        self.service_bank = 0
        self.sample_progress = 0

        self.fifos = [None for _ in range(banks)]
        self.pifos = [None for _ in range(banks)]
        self.global_root = None

        self.policy = make_policy(run["policy"])
        self.id_map = {}
        self.slots = {}
        self.log = []

    # -- sampling and repartition -----------------------------------------
    def _sample(self):
        ranges = len(self.history)
        captured = [0 for _ in range(ranges)]
        for lb in self.counters:
            for row in lb:
                for r in range(ranges):
                    captured[r] += row[r]

        # Normalise each fixed (load balancer, range) row over banks.
        for lb in self.counters:
            for r in range(ranges):
                minimum = min(row[r] for row in lb)
                if minimum:
                    for row in lb:
                        row[r] -= minimum

        new_history = [self.history[r] // 2 + captured[r]
                       for r in range(ranges)]
        self.history = new_history
        self.sample_progress = 0
        return captured, new_history

    @staticmethod
    def _migrate_vector(vector, old_borders, new_borders):
        new_ranges = len(new_borders) - 1
        result = [0 for _ in range(new_ranges)]
        for old_index, mass in enumerate(vector):
            if mass == 0:
                continue
            begin = old_borders[old_index]
            end = old_borders[old_index + 1]
            length = end - begin
            # Prefix mass at every new boundary.  Telescoping these values
            # is exactly the clamp/floor formula in the protocol.
            prefix = []
            for x in new_borders:
                offset = x - begin
                if offset <= 0:
                    prefix.append(0)
                elif offset >= length:
                    prefix.append(mass)
                else:
                    prefix.append((mass * offset) // length)
            for k in range(new_ranges):
                result[k] += prefix[k + 1] - prefix[k]
        return result

    def _repartition(self, new_borders):
        new_borders = [int(x) for x in new_borders]
        old_borders = self.borders
        new_counters = []
        for lb in self.counters:
            new_lb = []
            for row in lb:
                new_lb.append(self._migrate_vector(
                    row, old_borders, new_borders))
            new_counters.append(new_lb)
        new_history = self._migrate_vector(
            self.history, old_borders, new_borders)
        self.counters = new_counters
        self.history = new_history
        self.borders = new_borders

    # -- resident lookup ---------------------------------------------------
    def _locate(self, pkt_id):
        pkt = self.id_map.get(pkt_id)
        if pkt is None:
            return None, None, None
        lag, stored = g_get_lag(self.global_root, pkt.key)
        if lag is None:
            return None, None, None
        # The packet's metadata is immutable, and there is at most one live
        # copy of an emulated packet in the active branch.
        q = stored.bank
        if p_find(self.pifos[q], stored.key):
            return stored, lag, "pifo"
        if f_find(self.fifos[q], stored.ordinal):
            return stored, lag, "fifo"
        return None, None, None

    # -- refill and pushout ------------------------------------------------
    def _refill(self, q):
        fifo_root = self.fifos[q]
        if fifo_root is None:
            self.fifos[q] = None
        else:
            take = self.refill_batch
            if take > fifo_root.size:
                take = fifo_root.size
            moved, remaining = f_split_count(fifo_root, take)
            self.fifos[q] = remaining

            pifo_root = self.pifos[q]
            for pkt in f_collect(moved):
                pifo_root = p_insert(pifo_root, pkt)
            self.pifos[q] = pifo_root

        retained, evicted = p_take_prefix(
            self.pifos[q], self.pifo_capacity)
        self.pifos[q] = retained

        evicted_ids = []
        if evicted is not None:
            evicted_packets = p_collect(evicted)
            # p_collect is ascending (rank, ordinal); output is descending.
            for pkt in reversed(evicted_packets):
                self.global_root = g_delete(self.global_root, pkt.key)
                evicted_ids.append(pkt.id)
        return evicted_ids

    # -- events ------------------------------------------------------------
    def enqueue(self, index, pkt_id, flow, length, flow_size):
        # A rank attempt always advances policy state, even if admission
        # subsequently fails.
        rank = self.policy.attempt(flow, length, flow_size)
        rank = self.policy.attempt(flow, length, flow_size)
        upper = self.borders[-1]
        classified = rank if rank < upper else upper - 1
        if classified < self.borders[0]:
            classified = self.borders[0]
        range_index = bisect_right(self.borders, classified) - 1
        if range_index < 0:
            range_index = 0
        elif range_index >= len(self.borders) - 1:
            range_index = len(self.borders) - 2

        used_lb = self.load_balancer
        self.load_balancer = (used_lb + 1) % self.load_balancers

        row = self.counters[used_lb]
        best_bank = 0
        best_count = row[0][range_index]
        for q in range(1, self.banks):
            count = row[q][range_index]
            if count < best_count:
                best_count = count
                best_bank = q

        fifo_root = self.fifos[best_bank]
        used_bytes = fifo_root.bytes if fifo_root is not None else 0
        accepted = used_bytes + length <= self.fifo_capacity

        if accepted:
            pkt = Packet(pkt_id, flow, length, flow_size, rank, index,
                         best_bank)
            self.id_map[pkt_id] = pkt
            self.fifos[best_bank] = f_insert_last(fifo_root, pkt)
            self.global_root = g_insert(self.global_root, pkt)
            row[best_bank][range_index] += 1
            self.sample_progress += 1

        self.log.append([index, "enqueue", pkt_id, rank, used_lb,
                         range_index, best_bank, accepted])

        if accepted and self.sample_progress == self.sample_period:
            captured, new_history = self._sample()
            # `captured` and `new_history` are fresh lists, so later samples
            # cannot mutate this historical row.
            self.log.append([index, "sample", captured, new_history])

    def dequeue(self, index, count):
        for _ in range(count):
            old_tick = self.tick
            q = self.service_bank
            self.service_bank = (q + 1) % self.banks
            self.tick += 1

            evicted_ids = []
            root = self.pifos[q]
            if root is not None:
                # Already-nonempty PIFO: pop, feedback, then refill.
                pkt, root = p_pop_min(root)
                self.pifos[q] = root
                served_lag, stored = g_get_lag(
                    self.global_root, pkt.key)
                self.global_root = g_delete(self.global_root, pkt.key)
                self.policy.service(pkt.rank)
                evicted_ids = self._refill(q)
                rank_error, self.global_root = \
                    g_less_rank_and_increment(
                        self.global_root, pkt.rank)
                self.log.append([
                    index, "dequeue", old_tick, q, pkt.id, pkt.rank,
                    rank_error, served_lag, evicted_ids,
                ])
            else:
                # Empty PIFO: refill first, and (if possible) pop exactly one.
                evicted_ids = self._refill(q)
                root = self.pifos[q]
                if root is not None:
                    pkt, root = p_pop_min(root)
                    self.pifos[q] = root
                    served_lag, stored = g_get_lag(
                        self.global_root, pkt.key)
                    self.global_root = g_delete(self.global_root, pkt.key)
                    self.policy.service(pkt.rank)
                    rank_error, self.global_root = \
                        g_less_rank_and_increment(
                            self.global_root, pkt.rank)
                    self.log.append([
                        index, "dequeue", old_tick, q, pkt.id, pkt.rank,
                        rank_error, served_lag, evicted_ids,
                    ])
                else:
                    self.log.append([
                        index, "dequeue", old_tick, q, None, None, 0, 0,
                        evicted_ids,
                    ])

    def sample(self, index):
        captured, new_history = self._sample()
        self.log.append([index, "sample", captured, new_history])

    def repartition(self, index, new_borders):
        self._repartition(new_borders)
        self.log.append([index, "repartition", len(new_borders) - 1])

    def cancel(self, index, pkt_id):
        pkt, lag, stage = self._locate(pkt_id)
        if pkt is None:
            self.log.append([index, "cancel", pkt_id, None, None, None])
            return
        q = pkt.bank
        if stage == "pifo":
            self.pifos[q] = p_delete(self.pifos[q], pkt.key)
        else:
            self.fifos[q] = f_delete(self.fifos[q], pkt.ordinal)
        self.global_root = g_delete(self.global_root, pkt.key)
        self.log.append([index, "cancel", pkt_id, stage, q, lag])

    def inspect(self, index, pkt_id):
        pkt, lag, stage = self._locate(pkt_id)
        record = None
        if pkt is not None:
            record = [pkt.rank, pkt.bank, stage, pkt.length,
                      pkt.flow, lag]
        self.log.append([index, "inspect", pkt_id, record])

    def weight(self, index, flow, new_weight):
        self.policy.update_weight(flow, new_weight)
        self.log.append([index, "weight", flow, new_weight])

    def save(self, index, name):
        self.slots[name] = Snapshot(self)
        self.log.append([index, "save", name])

    def restore(self, index, name):
        snap = self.slots[name]
        self.tick = snap.tick
        self.load_balancer = snap.load_balancer
        self.service_bank = snap.service_bank
        self.sample_progress = snap.sample_progress
        self.borders = list(snap.borders)
        self.counters = [
            [list(row) for row in lb]
            for lb in snap.counters
        ]
        self.history = list(snap.history)
        self.policy.restore(snap.policy)
        self.fifos = list(snap.fifos)
        self.pifos = list(snap.pifos)
        self.global_root = snap.global_root
        self.log.append([index, "restore", name])

    # -- final certificate -------------------------------------------------
    def certificate(self):
        queues = []
        for q in range(self.banks):
            fifo_root = self.fifos[q]
            pifo_root = self.pifos[q]
            fifo_ids = [pkt.id for pkt in f_collect(fifo_root)]
            pifo_ids = [pkt.id for pkt in p_collect(pifo_root)]
            queues.append({
                "fifo": fifo_ids,
                "pifo": pifo_ids,
                "fifo_bytes": fifo_root.bytes
                if fifo_root is not None else 0,
                "pifo_bytes": pifo_root.bytes
                if pifo_root is not None else 0,
            })
        lags = sorted(g_collect_lags(self.global_root))
        return {
            "tick": self.tick,
            "load_balancer": self.load_balancer,
            "service_bank": self.service_bank,
            "sample_progress": self.sample_progress,
            "borders": list(self.borders),
            "counters": self.counters,
            "history": self.history,
            "policy": self.policy.certificate(),
            "queues": queues,
            "lags": [[pkt_id, lag] for pkt_id, lag in lags],
        }


def run_one(run):
    engine = RunEngine(run)
    for index, event in enumerate(run["events"]):
        command = event[0]
        if command == "enqueue":
            engine.enqueue(index, event[1], event[2], event[3], event[4])
        elif command == "dequeue":
            engine.dequeue(index, event[1])
        elif command == "sample":
            engine.sample(index)
        elif command == "repartition":
            engine.repartition(index, event[1])
        elif command == "cancel":
            engine.cancel(index, event[1])
        elif command == "inspect":
            engine.inspect(index, event[1])
        elif command == "weight":
            engine.weight(index, event[1], event[2])
        elif command == "save":
            engine.save(index, event[1])
        elif command == "restore":
            engine.restore(index, event[1])
        else:
            raise ValueError("unknown command")
    return {"log": engine.log, "state": engine.certificate()}


def run_request(request):
    return {"runs": [run_one(run) for run in request["runs"]]}
